def invertObject(obj):
    res = {}
    items = obj.items() if isinstance(obj, dict) else enumerate(obj)
    for k, v in items:
        k = str(k)
        if v not in res:
            res[v] = k
        elif isinstance(res[v], list):
            res[v].append(k)
        else:
            res[v] = [res[v], k]
    return res

