// C++ has no native JSON; a representative inversion over map<string,string>:
#include <map>
#include <vector>
#include <string>
std::map<std::string, std::vector<std::string>> invertObject(const std::map<std::string, std::string>& obj) {
    std::map<std::string, std::vector<std::string>> res;
    for (auto& [k, v] : obj) res[v].push_back(k);
    return res;
}

