// Java representative inversion over Map<String,String>:
java.util.Map<String, java.util.List<String>> invertObject(java.util.Map<String, String> obj) {
    java.util.Map<String, java.util.List<String>> res = new java.util.HashMap<>();
    for (java.util.Map.Entry<String, String> e : obj.entrySet())
        res.computeIfAbsent(e.getValue(), x -> new java.util.ArrayList<>()).add(e.getKey());
    return res;
}

