var invertObject = function(obj) {
    const res = {};
    for (const k in obj) {
        const v = obj[k];
        if (!Object.prototype.hasOwnProperty.call(res, v)) {
            res[v] = k;
        } else if (Array.isArray(res[v])) {
            res[v].push(k);
        } else {
            res[v] = [res[v], k];
        }
    }
    return res;
};
